  std::any parseTrade(std::any trade, std::any market = std::any{}) override {
    std::any timestamp =
        this->safeTimestamp(trade, std::string("created_at_int"));
    std::any id = this->safeString(trade, std::string("uuid"));
    market = this->safeMarket(std::any{}, market);
    std::any side = this->safeString(trade, std::string("side"));
    std::any price = this->safeString(trade, std::string("price"));
    std::any amountField =
        add(std::string("traded_"),
            toLowerCase(::getValue(market, std::string("base"))));
    std::any amount = this->safeString(trade, amountField);
    return this->safeTrade(
        ccxt::dict{
            {std::string("info"), trade},
            {std::string("id"), id},
            {std::string("order"), std::any{}},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("symbol"), ::getValue(market, std::string("symbol"))},
            {std::string("type"), std::any{}},
            {std::string("side"), side},
            {std::string("takerOrMaker"), std::any{}},
            {std::string("price"), price},
            {std::string("amount"), amount},
            {std::string("cost"), std::any{}},
            {std::string("fee"), std::any{}},
        },
        market);
  }

